using System.ComponentModel;
using System.Net;
using System.Text.Json;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI;

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running this app.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

// --- Build the chat client through the MEAI abstraction ---
IChatClient chatClient = new OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

// --- Define the agent tools ---
var tools = new AITool[]
{
    AIFunctionFactory.Create(WebSearchTool.SearchAsync),
    AIFunctionFactory.Create(NotesTool.AddNote),
    AIFunctionFactory.Create(NotesTool.GetNotes),
};

// --- Create the research agent ---
var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research agent. When given a topic you:
        1. Search the web for information using several varied queries.
        2. Take notes on the key findings using the note-taking tool.
        3. After gathering enough information, retrieve your notes and
           produce a concise, well-structured summary with key points.
        Always cite your sources.
        """,
    name: "ResearchAgent",
    description: "Researches a topic by searching the web and summarizing findings.",
    tools: tools);

var chatOptions = new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 2048,
};

var runOptions = new ChatClientAgentRunOptions(chatOptions);

// --- Main interaction loop ---
Console.WriteLine("🔍 Research Agent ready. Type a topic to research (or 'quit' to exit).\n");

while (true)
{
    Console.Write("Topic> ");
    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    NotesTool.Clear();
    Console.WriteLine($"\nResearching: {topic}\n");

    var session = await agent.CreateSessionAsync();
    var result = await agent.RunAsync(
        $"Research the following topic and provide a comprehensive summary: {topic}",
        session,
        runOptions);

    foreach (var message in result.Messages)
    {
        if (message.Role == ChatRole.Assistant && !string.IsNullOrWhiteSpace(message.Text))
        {
            Console.WriteLine(message.Text);
        }
    }

    Console.WriteLine();
}

Console.WriteLine("Goodbye!");

// ────────────────────────────────────────────────────────────────────
// Tool definitions
// ────────────────────────────────────────────────────────────────────

/// <summary>Simulated web search tool that fetches real pages via Bing.</summary>
static class WebSearchTool
{
    private static readonly HttpClient Http = new()
    {
        DefaultRequestHeaders =
        {
            { "User-Agent", "ResearchAgent/1.0" },
            { "Accept-Language", "en-US" },
        },
        Timeout = TimeSpan.FromSeconds(15),
    };

    [Description("Search the web for information on a query. Returns a list of result snippets.")]
    public static async Task<string> SearchAsync(
        [Description("The search query string")] string query)
    {
        try
        {
            var encoded = WebUtility.UrlEncode(query);
            var url = $"https://html.duckduckgo.com/html/?q={encoded}";
            var html = await Http.GetStringAsync(url);

            var results = ParseResults(html);
            if (results.Count == 0)
                return $"No results found for: {query}";

            return JsonSerializer.Serialize(new { query, results },
                new JsonSerializerOptions { WriteIndented = true });
        }
        catch (Exception ex)
        {
            return $"Search failed for '{query}': {ex.Message}";
        }
    }

    private static List<object> ParseResults(string html)
    {
        var results = new List<object>();
        var snippetMarker = "result__snippet";
        var titleMarker = "result__a";
        var idx = 0;

        while (results.Count < 5 && idx < html.Length)
        {
            idx = html.IndexOf(titleMarker, idx, StringComparison.Ordinal);
            if (idx < 0) break;

            var title = ExtractTagContent(html, idx);
            var snippetIdx = html.IndexOf(snippetMarker, idx, StringComparison.Ordinal);
            var snippet = snippetIdx >= 0 ? ExtractTagContent(html, snippetIdx) : "";

            if (!string.IsNullOrWhiteSpace(title))
            {
                results.Add(new { title = CleanHtml(title), snippet = CleanHtml(snippet) });
            }

            idx += titleMarker.Length;
        }

        return results;
    }

    private static string ExtractTagContent(string html, int startIdx)
    {
        var gt = html.IndexOf('>', startIdx);
        if (gt < 0) return "";
        var close = html.IndexOf('<', gt + 1);
        if (close < 0) return "";
        return html[(gt + 1)..close];
    }

    private static string CleanHtml(string text) =>
        WebUtility.HtmlDecode(text).Trim();
}

/// <summary>Note-taking tool the agent uses to collect research findings.</summary>
static class NotesTool
{
    private static readonly List<string> Notes = [];

    [Description("Save a research note. Use this to record key findings from searches.")]
    public static string AddNote(
        [Description("The note content to save")] string note)
    {
        Notes.Add(note);
        return $"Note #{Notes.Count} saved.";
    }

    [Description("Retrieve all saved research notes.")]
    public static string GetNotes()
    {
        if (Notes.Count == 0) return "No notes saved yet.";

        return string.Join("\n", Notes.Select((n, i) => $"[{i + 1}] {n}"));
    }

    public static void Clear() => Notes.Clear();
}

